implementation_guidance:
③ 房主/继任者选择（混合大陆+海外）：对每个候选 c 计算 cost(c) = max_i RTT(c,i) 为主，sum_i RTT(c,i)/n 为辅，取最小者；人数少的一方忍受全部延迟，所以用 max（最差玩家）而不是平均。D2 换主时继任者按 cost 排序，前 2 名提前建立备用连接。伪代码：
  func pick_host(cands: Array) -> int:
    var best := -1; var best_cost := INF
    for c in cands:
      var worst := 0.0; var total := 0.0
      for p in members:
        if p == c: continue
        var r = Steam.estimatePingTimeBetweenTwoLocations(ploc[c], ploc[p])
        if r < 0: r = 300
        worst = max(worst, r); total += r
      var cost = worst + 0.25 * total / max(1, members.size() - 1)
      if cost < best_cost: best_cost = cost; best = c
    return best
